/**
 * Build the native icon and splash sources from the canonical brand cutout.
 *
 * Run from the repository root:
 *
 *   node scripts/build-native-icons.mjs
 *   cd apps/web && npx @capacitor/assets generate --iconBackgroundColor '#010118' \
 *     --iconBackgroundColorDark '#010118' --splashBackgroundColor '#010118' \
 *     --splashBackgroundColorDark '#010118'
 *
 * WHY THIS IS A SCRIPT AND NOT SEVEN CHECKED IN PNGS SOMEBODY MADE ONCE.
 *
 * The web PWA icons under `apps/web/public/pwa` were generated by hand from the
 * same source and there is no record of how. When the brand mark next changes,
 * whoever redraws it has to reverse engineer the padding, the background and
 * the safe zone from the pixels. This file is that record, and running it again
 * reproduces every source byte for byte.
 *
 * THE SOURCE IS A LOCKUP AND THE ICON MUST NOT BE.
 *
 * `rentme-logo.png` is the full lockup: the house-and-R mark, the RENT ME
 * wordmark under it, and a FIND IT. RENT IT. LOVE IT. tagline under that. An
 * app icon is read at 48px on a home screen, where a wordmark is mush and a
 * tagline is a smudge, and both stores mark down icons carrying small text. So
 * the mark is cut out of the lockup first. The box below was measured from the
 * source's own alpha channel rather than guessed: the ink stops at row 597 and
 * there are sixty empty rows before the wordmark begins, so the cut is
 * unambiguous. It matches the treatment already shipped in
 * `public/pwa/icon-512.png`, which was cropped the same way by hand.
 *
 * THE ONE UPSCALE, NAMED RATHER THAN HIDDEN.
 *
 * The mark inside that lockup is 511x598. Apple requires a 1024x1024 App Store
 * icon, and there is no way to make one from a 598px master without enlarging
 * it. There is no vector: `design-system/brand/Logo.tsx` renders this same PNG,
 * so this file is the largest master that exists.
 *
 * So `icon-only.png` enlarges the mark about 1.5x, with lanczos3, which is the
 * right kernel for artwork that is large flat shapes and smooth gradients
 * rather than fine detail. The adaptive foreground is about 1.06x, effectively
 * native size, and both splash images are a genuine DOWNSCALE. Nothing else
 * here is enlarged.
 *
 * This is the honest state and not the desirable one. A 1024px or vector master
 * of the mark alone removes the compromise entirely, and it is on the owner
 * action list in `docs/MOBILE.md` for exactly that reason.
 *
 * The mark is composed onto the brand navy rather than shipped transparent,
 * because a transparent icon is painted onto whatever the launcher feels like,
 * and this brand is dark by default and must not be read on white.
 */

import { mkdir, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";
import sharp from "sharp";

const ROOT = path.join(path.dirname(fileURLToPath(import.meta.url)), "..");
const SOURCE = path.join(ROOT, "apps/web/public/brand/rentme-logo.png");
const OUT = path.join(ROOT, "apps/web/assets");

/** Sampled brand anchors. `tokens.css` layer 1 is the authority for both. */
const NAVY = { r: 1, g: 1, b: 24, alpha: 1 };

/**
 * How much of each canvas the mark occupies, on its longest edge.
 *
 * `icon` is the plain square icon, where the mark can sit fairly large because
 * nothing crops it.
 *
 * `foreground` is the Android adaptive layer, and it is deliberately much
 * smaller. An adaptive icon is masked by the launcher into a circle, a
 * squircle, a rounded square or a teardrop depending on the device, and only
 * the inner 66 of 108 units is guaranteed to survive every mask.
 *
 * The number compounds, which is the part that is easy to get wrong. Capacitor
 * writes an `<inset android:inset="16.7%">` around BOTH adaptive layers, so the
 * drawable is already reduced to the inner 72 of 108 units before this scale
 * applies. At 0.55 the mark ends up around 0.61 of the guaranteed circle's
 * diameter, which was checked by compositing the two generated mipmaps and
 * masking them at the real 66 of 108 rather than by reading the number. 0.62
 * was tried first and the mark's leg sat almost on the circle's edge.
 *
 * `splash` is small because a splash screen is a held breath, not a poster,
 * and because the same image is centred on both phone and tablet.
 */
const SCALE = { icon: 0.88, foreground: 0.55, splash: 0.2 };

/**
 * The house-and-R mark inside the lockup, measured from the source's alpha.
 *
 * Row 597 is the last row carrying ink before a sixty row gap and then the
 * wordmark. Re-measure with the profiling snippet in this file's history if the
 * brand artwork is ever replaced; do not nudge these numbers by eye.
 */
const MARK = { left: 193, top: 0, width: 511, height: 598 };

/** Compose the mark, centred, on a canvas of `size`, over `background`. */
async function compose(size, scale, background, file) {
  const mark = await sharp(SOURCE)
    .extract(MARK)
    .resize({
      width: Math.round(size * scale),
      height: Math.round(size * scale),
      /* `inside` preserves the mark's 511x598 aspect ratio exactly. `fill`
         would stretch it, which is the thing the brief forbids by name. */
      fit: "inside",
      /* Lanczos, because one target genuinely does enlarge. See the header. */
      kernel: "lanczos3",
    })
    .toBuffer();

  const canvas = sharp({
    create: { width: size, height: size, channels: 4, background },
  });

  await canvas
    .composite([{ input: mark, gravity: "centre" }])
    .png({ compressionLevel: 9 })
    .toFile(path.join(OUT, file));

  const { width, height, size: bytes } = await sharp(path.join(OUT, file)).metadata();
  console.log(`  ${file.padEnd(24)} ${width}x${height}  ${Math.round((bytes ?? 0) / 1024)}kB`);
}

const TRANSPARENT = { r: 0, g: 0, b: 0, alpha: 0 };

await mkdir(OUT, { recursive: true });
console.log("Native icon and splash sources, from public/brand/rentme-logo.png:");

/* The plain icon. @capacitor/assets uses this for iOS, where there is no
   adaptive layering and the mask is a fixed superellipse. */
await compose(1024, SCALE.icon, NAVY, "icon-only.png");

/* The Android adaptive pair. Foreground is transparent by definition: the
   launcher composites it over the background layer and animates the two
   independently on some devices. */
await compose(1024, SCALE.foreground, TRANSPARENT, "icon-foreground.png");

/* A flat navy plate. Nothing is drawn on it, and nothing should be: any detail
   here shows through the parallax on launchers that separate the layers. */
await sharp({ create: { width: 1024, height: 1024, channels: 4, background: NAVY } })
  .png({ compressionLevel: 9 })
  .toFile(path.join(OUT, "icon-background.png"));
console.log(`  ${"icon-background.png".padEnd(24)} 1024x1024  flat navy`);

/*
 * 2732 square is the size that covers every device without upscaling, because
 * the tooling centre crops it to each screen. Both themes get the same navy
 * image on purpose: dark is the default and the operating system does not
 * override it, so a light splash would be the one moment the brand let the
 * device decide.
 */
await compose(2732, SCALE.splash, NAVY, "splash.png");
await compose(2732, SCALE.splash, NAVY, "splash-dark.png");

/*
 * A guard, so the one enlargement stays the one enlargement.
 *
 * It does not forbid enlarging, because the App Store icon has no choice. It
 * caps how far, so nobody quietly raises a scale factor to 2x and ships a soft
 * icon. If this throws, the answer is a bigger master, not a bigger number.
 */
const LARGEST_ACCEPTABLE_ENLARGEMENT = 1.6;
for (const [name, scale] of Object.entries(SCALE)) {
  const canvas = name === "splash" ? 2732 : 1024;
  const factor = (canvas * scale) / MARK.height;
  console.log(`  ${name.padEnd(12)} scale factor ${factor.toFixed(2)}x`);
  if (factor > LARGEST_ACCEPTABLE_ENLARGEMENT) {
    throw new Error(
      `${name} would enlarge the ${MARK.width}x${MARK.height} mark by ${factor.toFixed(2)}x, ` +
        `past the ${LARGEST_ACCEPTABLE_ENLARGEMENT}x ceiling. Supply a larger master instead.`,
    );
  }
}

await writeFile(
  path.join(OUT, "README.md"),
  [
    "# Native icon and splash sources",
    "",
    "Generated. Do not hand edit.",
    "",
    "`node scripts/build-native-icons.mjs` rebuilds every file here from",
    "`apps/web/public/brand/rentme-logo.png`, which is the canonical cutout.",
    "`npx @capacitor/assets generate` then fans these out into the Android and",
    "iOS projects. The script explains the scale factors and why none of them",
    "upscales the mark.",
    "",
  ].join("\n"),
  "utf8",
);

console.log("\nDone. Now run @capacitor/assets from apps/web to fan these out.");
